/**
 * Opens the repositories of fixture-search-db over db, a SqlDatabase, acting
 * as the user options names, or as the user it is when a string. The
 * behaviors' core is options.rules, or the rules package's, made when a
 * behavior first runs.
 */
export function createOrm(db: SqlDatabase, options?: string | null | OrmOptions): FixtureSearchDbOrm {
  return sqliteOrm<FixtureSearchDbRepositories>(db, fixtureSearchDbOrm, withRulesCore(options, initSync)) as FixtureSearchDbOrm;
}
